// Git roadmap questions (120): 15 levels × 8, easiest → hardest. Unlike the
// other roadmap topics (which interleave two authored sets), Git is authored as
// a single 8-per-level list and built directly. See lib/roadmap.ts for titles.

import type { Seed } from './roadmap-build';

export const gitSeeds: Seed[] = [
  // ── Level 1 — Version Control Basics ───────────────────────────────────
  { q: 'Developers need local history, branches, and the ability to exchange commits without a central server holding the only complete copy. Which tool model fits?', opts: ['A text editor with one undo history per file', 'Git, a distributed version control system', 'A package registry that stores published builds', 'A hosting service that owns the only copy of the history'], a: 1, e: 'Git is distributed version control: each clone normally holds the full history and can commit and branch with no network. A hosting service such as GitHub stores one more copy and adds review and permissions on top, but it does not own the history format; a package registry stores build artifacts, not commits.', intro: 'Ask of each option what it can actually store: file edits, build artifacts, or commits.', tags: ['Git', 'Basics'] },
  { q: 'What does a single commit represent?', opts: ['A backup of the project kept on a server', 'A snapshot of the tracked files at a point in time', 'A movable pointer to the tip of a line of work', 'A named URL for another copy of the repository'], a: 1, e: 'A commit records the content of all tracked files as of the moment you committed, together with author, committer, timestamps, message and its parent commit. A branch is only a movable pointer to such a snapshot and a remote is only a stored URL, so neither holds the content itself.', intro: 'Ask what a commit stores, not what it points at.', tags: ['Git', 'Basics'] },
  { q: 'How does Git model project history?', opts: ['As a single file', 'As a series of commits, each linked to its parent', 'As a database table', 'As a zip archive'], a: 1, e: 'Each commit stores the id of the commit it was built on (two or more for a merge; the very first commit has none), so the history is a graph Git can walk backwards. That is what makes `git log`, diffs between any two commits and merges possible; a zip archive or a single file would hold one state with no link from one version to the next, and Git keeps its objects as files under `.git`, not in a database table.', intro: 'Picture `git log` walking from the newest entry back to older ones, and ask what it follows.', tags: ['Git', 'Basics'] },
  { q: '"Distributed" version control means:', opts: ['Only the server has the history', 'Every clone contains the full history', 'History lives only in the cloud', 'There is no history'], a: 1, e: 'In a distributed system every clone is a complete repository: it holds the objects and refs for the whole history, so log, diff, branch and commit all work offline. A server copy is just another clone that everyone agrees to use as the meeting point, not the only place the history exists.', intro: 'Contrast it with a system where you must be online just to read last month\'s changes.', tags: ['Git', 'Basics'] },
  { q: 'Which hidden folder holds a Git repository’s data?', opts: ['`.svn`', '`.git`', '`.repo`', '`git/`'], a: 1, e: '`git init` creates a single hidden directory named `.git` at the repository root, and every object, ref, config value and HEAD lives inside it, so deleting it turns the folder back into ordinary files. `git/` without the leading dot is not hidden and is never created by Git; `.svn` is Subversion\'s per-directory metadata.', intro: 'Remember what `ls -a` shows in a folder right after `git init`.', tags: ['Git', 'Basics'] },
  { q: 'A tool requires Git 2.40 or newer. Which command checks the installed Git release without changing the repository?', opts: ['git status', 'git --version', 'git config --list', 'git log --max-count=1'], a: 1, e: '`git --version` prints the installed release (for example `git version 2.43.0`) and reads nothing from the repository, so it even works outside one. `git status` and `git log` report on the project\'s files and history and `git config --list` prints configuration, none of which tells you which Git build is installed.', intro: 'Ask which output would change if you upgraded Git tomorrow but left the project untouched.', tags: ['Git', 'Basics'] },
  { q: 'How is a commit identified?', opts: ['A sequential number', 'A SHA hash', 'A timestamp only', 'Its filename'], a: 1, e: 'A commit\'s id is a hash computed over its content and metadata (SHA-1 by default, SHA-256 in repositories created for it), so any two clones derive the same id independently and any change produces a different one. A sequential number would need a central authority to hand it out, which is what Subversion does and Git deliberately avoids.', intro: 'Two clones with no server between them must agree on the id: what could produce that?', tags: ['Git', 'Basics'] },
  { q: 'What does Git primarily track?', opts: ['CPU usage', 'Changes to files over time', 'Open browser tabs', 'Network traffic'], a: 1, e: 'Git records how your tracked files change across commits.', tags: ['Git', 'Basics'] },

  // ── Level 2 — Repositories ─────────────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git init\n```', opts: ['Copies an existing repository from a URL', 'Creates a new empty repository in the current folder', 'Removes version control from the current folder', 'Uploads the current folder to a remote'], a: 1, e: '`git init` creates the `.git` directory in the current folder and starts a repository with no commits yet; with `init.defaultBranch` unset, git 2.43 also prints a hint that it used `master` for the initial branch. Copying an existing repository is `git clone`, and nothing is sent anywhere until you add a remote and push.', intro: 'Notice the command carries no URL and no file name. Ask what it can act on.', tags: ['Git', 'Repositories'] },
  { q: 'What does this do?\n\n```bash\n$ git clone https://example.com/repo.git\n```', opts: ['Creates an empty repository in a new folder', 'Copies a remote repository locally, with its history', 'Uploads your local commits to a remote', 'Renames the current repository folder'], a: 1, e: '`git clone` copies a repository into a new local directory: all reachable commits, every branch as a remote-tracking ref, and a remote called `origin` pointing back at the URL. It creates the directory rather than starting an empty repository, and it transfers nothing in the other direction until you push.', intro: 'The command is handed someone else\'s URL. Ask what ends up in your folder when it finishes.', tags: ['Git', 'Repositories'] },
  { q: 'After cloning, what is the default remote called?', opts: ['`main`', '`origin`', '`remote`', '`upstream`'], a: 1, e: 'Clone registers the URL you cloned from as a remote named `origin`, which is why `origin/main` and `git push origin main` work without configuration (pass `-o <name>` to choose a different one). `upstream` is a name people add by hand in fork workflows for the original repository, and `main` is a branch, not a remote.', intro: 'Recall the name that shows up in `git remote -v` in a repository you have only cloned.', tags: ['Git', 'Remotes'] },
  { q: 'What is a "bare" repository?', opts: ['A repository that has no commits yet', 'A repository with no working tree, used as a push target', 'A repository that other people cannot clone', 'A repository whose files are all read-only'], a: 1, e: 'A bare repository contains only what normally sits inside `.git` (`core.bare=true`), so there are no checked-out files for an incoming push to conflict with, which is why server-side repositories are created bare. It still has commits, can still be cloned, and is not read-only.', intro: 'Picture running `ls` in a repository made with `git clone --bare`. Ask what is not there.', tags: ['Git', 'Repositories'] },
  { q: 'When you clone, which branch is checked out?', opts: ['No branch', 'The repository’s default branch (e.g. main)', 'All branches at once', 'A random branch'], a: 1, e: 'Clone fetches every branch as a remote-tracking ref but creates and checks out exactly one local branch: the one `origin/HEAD` points at, commonly `main`. The other branches are there (`git branch -r` lists them) and you can start from a different one with `--branch <name>`.', intro: 'Only one branch can be in your working tree at a time. Ask who gets to choose which.', tags: ['Git', 'Repositories'] },
  { q: 'What does this do?\n\n```bash\n$ git clone <url> app\n```', opts: ['Fails, because clone accepts only a URL', 'Clones into a folder named `app`', 'Renames the remote to `app`', 'Creates a branch named `app`'], a: 1, e: 'The optional second argument is the destination directory, so the repository lands in `app/` instead of the name derived from the URL. The remote is still called `origin` and no branch is created, because the argument names a place on disk, not a Git ref.', intro: 'Remote and branch names have their own flags (`-o`, `-b`). Ask what a bare extra word is left to name.', tags: ['Git', 'Repositories'] },
  { q: 'What state does this command create?\n\n```bash\n$ git init -b main\n```', opts: ['An empty repository with no branch name until the first push', 'A new repository whose initial branch is named main', 'A clone of a remote repository’s main branch', 'A new main branch inside the nearest parent repository'], a: 1, e: '`git init` starts a repository in the current directory and `-b main` sets the name of its initial branch, so HEAD points at `refs/heads/main` before the first commit exists. Without `-b`, git 2.43 uses `init.defaultBranch` and falls back to `master`, which is why the flag (or the config) is worth setting; nothing is cloned and no parent repository is touched.', intro: 'Two of these involve a remote or an existing repository. Check whether `git init` involves either.', tags: ['Git', 'Repositories'] },
  { q: 'Is copying a project folder (including `.git`) enough to copy the repo?', opts: ['No — the history lives on the server, not in the folder', 'Yes — the whole repository is inside `.git`', 'Only if the folder is also connected to a remote', 'Only the most recent commit is copied this way'], a: 1, e: 'Every object, ref and config value sits in `.git`, so a plain directory copy produces a working repository: `git log` in the copy shows the full history with no network and no remote. Nothing about the history is stored server-side, and a remote is only a place to exchange commits.', intro: 'Ask where the objects and refs are stored, then decide whether copying the folder takes them along.', tags: ['Git', 'Repositories'] },

  // ── Level 3 — Staging & Status ─────────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git add file.txt\n```', opts: ['Commits the file', 'Stages file.txt for the next commit', 'Deletes the file', 'Pushes the file'], a: 1, e: '`git add` copies the file\'s current content into the index, so it is queued for the next commit but nothing is recorded in history yet — `git status` lists it under \'Changes to be committed\' and `git log` is unchanged. Committing is a separate command, and nothing is deleted or sent to a remote.', intro: 'Ask what would be missing if you stopped here and never ran `git commit`.', tags: ['Git', 'Staging'] },
  { q: 'What does `git status` show?', opts: ['The commit history', 'Staged, unstaged and untracked changes', 'Remote branches', 'A full diff'], a: 1, e: '`git status` reports the state of your working tree in three groups — staged for the next commit, changed but not staged, and untracked — plus the branch and its relation to its upstream. It names files rather than printing their contents; the line-by-line changes come from `git diff`, and history comes from `git log`.', intro: 'Think about what `git status` summarizes versus what `git diff` prints in full.', tags: ['Git', 'Staging'] },
  { q: 'The staging area is also known as the:', opts: ['Reflog', 'Index', 'Stash', 'Working tree'], a: 1, e: 'The staging area is the index — literally `.git/index`, the file holding the snapshot your next commit will record. The stash is a separate place for shelved changes, the reflog records where refs have pointed over time, and the working tree is the checked-out files themselves.', intro: 'Recall the name of the file inside `.git` that holds what you have staged.', tags: ['Git', 'Staging'] },
  { q: 'From the repository root, what does this add to the index?\n\n```bash\n$ git add .\n```', opts: ['Only untracked files, leaving edits and deletions unstaged', 'New, modified, and deleted paths under the current directory', 'Every change in every Git worktree on the machine', 'Only deletions already recorded in the last commit'], a: 1, e: '`git add .` stages every change under the current path: files added, modified and deleted alike, which `git status --short` then shows as `A`, `M` and `D` entries. Its scope is the directory you are standing in, so running it from a subdirectory leaves changes elsewhere in the repository unstaged; `git add -A` from anywhere covers the whole worktree.', intro: 'Two questions decide it: which paths does `.` cover, and does a deletion count as a change?', tags: ['Git', 'Staging'] },
  { q: 'You create a new file, have not run `git add`, and no ignore rule matches it. In `git status` that file is:', opts: ['Staged', 'Modified', 'Untracked', 'Ignored'], a: 2, e: 'A file Git has no record of is untracked, and `git status` lists it under \'Untracked files\' until you `git add` it. \'Staged\' and \'modified\' both describe files Git already tracks, and \'ignored\' applies only when a `.gitignore` rule matches — ignored files are untracked too, but `git status` hides them unless you pass `--ignored`.', intro: 'Git can only report a change to a file it already follows; decide whether this one qualifies.', tags: ['Git', 'Staging'] },
  { q: 'What does this do?\n\n```bash\n$ git restore --staged file.txt\n```', opts: ['Deletes the file', 'Unstages it, keeping your changes', 'Commits it', 'Ignores it'], a: 1, e: 'With `--staged`, restore copies the file back from HEAD into the index only, so the file leaves the staged section and your edits stay in the working tree (`MM` becomes ` M`). Without `--staged`, `git restore file.txt` overwrites the working-tree copy from the index and does throw those edits away — that is the difference worth remembering.', intro: '`--staged` decides which copy of the file the command rewrites: the index or the one on disk.', tags: ['Git', 'Staging'] },
  { q: 'What does this do?\n\n```bash\n$ git add -p\n```', opts: ['Stages whole files only', 'Lets you stage changes interactively, hunk by hunk', 'Prints a patch', 'Pushes patches'], a: 1, e: '`-p` walks the file\'s diff hunk by hunk and asks whether to stage each one, so you can commit a bug fix without the debug print sitting next to it. The file then shows as `MM` in `git status`: part of it staged, part still only in the working tree. Without `-p`, `git add` always stages the file\'s whole current content.', intro: 'Picture a file holding both a bug fix and a stray debug line. What would you want to stage?', tags: ['Git', 'Staging'] },
  { q: 'You staged a file, then edited it again. What must you do to include the new edits?', opts: ['Nothing — staging follows the file from now on', 'Run `git add` again to stage the newer edits', 'Commit twice so both versions are recorded', 'Stash the file and then commit it'], a: 1, e: '`git add` copies the file\'s content into the index, so edits made afterwards live only in the working tree: `git status` shows the file in both sections (`MM`) and a commit now would record the older content. Running `git add` again refreshes the staged copy, and `git commit -a` would also pick it up because the file is already tracked.', intro: 'Run `git status` in your head: how many sections does the file show up in now?', tags: ['Git', 'Staging'] },

  // ── Level 4 — Committing ───────────────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git commit -m "Add login"\n```', opts: ['Stages the changed files for committing', 'Records the staged changes as a commit with that message', 'Sends the current branch to the remote', 'Creates a branch named after the message'], a: 1, e: '`git commit` turns whatever is in the index into a new commit on the current branch, and `-m` supplies the message inline instead of opening an editor. Anything you did not stage — including untracked files — stays out of the commit, and nothing is sent anywhere until you push.', intro: 'Ask which of these four steps you would already have done before typing this line.', tags: ['Git', 'Committing'] },
  { q: 'What does the -a flag do here?\n\n```bash\n$ git commit -am "Fix"\n```', opts: ['Commits untracked files too', 'Stages already-tracked modified files, then commits', 'Only commits', 'Amends the last commit'], a: 1, e: '`-a` stages the current state of every file Git already tracks — including tracked files you deleted — and then commits, so it is a shortcut for `git add -u` plus `git commit`. A brand-new file has never been added, so it stays untracked and is silently left out; that is why `git status` before committing is still worth the two seconds.', intro: '`-a` saves you one command you would normally run first. Ask exactly which command it stands in for.', tags: ['Git', 'Committing'] },
  { q: 'What does this do?\n\n```bash\n$ git commit --amend\n```', opts: ['Adds a second commit on top of the last one', 'Replaces the previous commit, message and content', 'Removes the last commit and the work in it', 'Sends the last commit to the remote'], a: 1, e: '`--amend` builds a replacement for the most recent commit from the current index and the message you give it, so history keeps the same length but the tip gets a new hash. The work is not lost the way a hard reset would lose it, but because the id changes, publishing an amended commit needs a force push and leaves anyone who already pulled the old one with a rewritten history to reconcile.', intro: 'Count the commits before and after: does the history get any longer?', tags: ['Git', 'Committing'] },
  { q: 'Your working tree is clean and nothing is staged. What does `git commit -m "wip"` do?', opts: ['Records a commit with no changes in it', 'Reports that there is nothing to commit and stops', 'Leaves the repository in a broken state', 'Removes the previous commit from history'], a: 1, e: 'With an empty index Git prints `nothing to commit, working tree clean`, exits non-zero and creates no commit object, so history is untouched. An empty commit is possible but you have to ask for it with `--allow-empty`; nothing here damages the repository or removes anything.', intro: 'Picture `git status` first: is there anything for the commit to record?', tags: ['Git', 'Committing'] },
  { q: 'What makes a commit message useful to someone reading the history months later?', opts: ['A single word, so the log stays short', 'A concise summary of what changed and why', 'A copy of the diff for the changed files', 'The date and author of the change'], a: 1, e: 'The diff already shows what the code does now, so the message has to carry the part the diff cannot: the intent behind the change. Git records the author and date itself, and pasting the diff into the message only duplicates what `git show` prints, while a one-word message sends the reader back into the diff to guess.', intro: 'Imagine `git log --oneline` six months from now: what would you need that line to tell you?', tags: ['Git', 'Committing'] },
  { q: 'What identity metadata does a commit store?', opts: ['Just a username', 'Author/committer name, email and timestamp', 'An IP address', 'Only a SHA'], a: 1, e: 'A commit object stores an `author` line and a `committer` line, each with a name, an email address and a timestamp, alongside the tree, the parents and the message. The SHA is not stored inside the commit at all — it is computed from that content — and Git records no network identity such as an IP address.', intro: 'Recall the two lines `git cat-file -p HEAD` prints above the message.', tags: ['Git', 'Committing'] },
  { q: 'What does `HEAD` refer to?', opts: ['The first commit in the repository', 'The commit you currently have checked out', 'The default remote of the repository', 'The snapshot waiting in the staging area'], a: 1, e: 'HEAD is the reference to where you are: normally a symbolic ref to the checked-out branch, whose tip becomes the parent of your next commit, and in detached HEAD a direct pointer to a commit. It is not the first commit (that has no parent), not a remote, and not the index.', intro: 'Think about what Git must know to give your next commit a parent.', tags: ['Git', 'Committing'] },
  { q: 'What does this local Git setting affect?\n\n```bash\n$ git config user.email "me@x.com"\n```', opts: ['The credentials used to authenticate every GitHub request', 'The author email recorded on commits created in this repository', 'The SSH key selected when pushing to a remote', 'The address that receives repository notifications'], a: 1, e: '`user.email` is identity metadata: without `--global` it is written to this repository\'s `.git/config` and stamped on the author and committer lines of commits you make here. Authentication uses credentials or an SSH key configured elsewhere, and hosting-side notifications are a platform setting — changing `user.email` affects none of them.', intro: 'Decide whether this value is used when Git writes a commit or when Git talks to a server.', tags: ['Git', 'Committing'] },

  // ── Level 5 — History & Diffs ──────────────────────────────────────────
  { q: 'You need the ordered commits reachable from the current branch, including author, date, and message. Which command starts that investigation?', opts: ['git diff', 'git log', 'git branch --list', 'git remote -v'], a: 1, e: '`git log` walks the commits reachable from HEAD, newest first, printing hash, author, date and message for each; flags then reshape it (`--oneline`, `--graph`, a path after `--`). `git diff` compares file contents rather than listing commits, `git branch --list` names branches, and `git remote -v` prints URLs.', intro: 'Ask which of these walks the commit graph rather than describing the current state.', tags: ['Git', 'History'] },
  { q: 'What does `git log --oneline` do?', opts: ['Shows full details', 'Shows one compact line per commit', 'Shows only the latest commit', 'Shows a graph only'], a: 1, e: '`--oneline` is shorthand for `--pretty=oneline --abbrev-commit`: every commit becomes an abbreviated hash plus its subject, which is what makes history scannable or pipeable. It still shows every commit — limiting the count is `-n`/`--max-count` — and the branch topology only appears if you add `--graph`.', intro: 'Ask whether the flag changes how many commits you see or how much of each one.', tags: ['Git', 'History'] },
  { q: 'With no arguments, `git diff` shows:', opts: ['Staged changes', 'Unstaged changes (working tree vs index)', 'The last commit', 'A remote diff'], a: 1, e: 'With no arguments `git diff` compares the working tree against the index, so it shows exactly the edits you have not staged yet. What you have staged is invisible to it — that needs `git diff --staged` — and a commit-to-commit comparison needs the revisions named explicitly.', intro: 'Two comparisons are possible here; decide which pair Git picks when you give it no arguments.', tags: ['Git', 'History'] },
  { q: 'Before committing, which comparison does `git diff --staged` display?', opts: ['The working tree against the index', 'The index against the current commit', 'Every pair of commits on the branch', 'The local branch against its remote without fetching'], a: 1, e: '`--staged` compares the index against HEAD, so it shows precisely the change the next commit would record. `--cached` is a synonym and prints exactly the same output. Working-tree edits you have not staged are excluded — that is plain `git diff` — and no network access is involved.', intro: 'You are about to commit: which two versions does that review need to compare?', tags: ['Git', 'History'] },
  { q: 'What does `git show <commit>` display?', opts: ['Only the message', 'A commit’s metadata and its diff', 'Only the file list', 'Branches'], a: 1, e: '`git show <commit>` prints the commit header — hash, author, date, message — and then the patch that commit introduced, which is the quickest way to review a single change. `git log` gives the headers for many commits but no patches unless you add `-p`, and `--stat` alone would give only the file list.', intro: 'Think about what you would need to review one commit without running two commands.', tags: ['Git', 'History'] },
  { q: 'What does `git log --graph` add?', opts: ['It hides merges', 'An ASCII graph of branches and merges', 'An exported image', 'Sorting by size'], a: 1, e: '`--graph` draws the commit topology in ASCII down the left margin, so merges and parallel lines of work are visible in the terminal (it is usually paired with `--oneline --all`). It makes merges more visible rather than hiding them, and it produces text in the terminal, not an exported image.', intro: 'Try it on a history that contains a merge and compare the output with plain `git log`.', tags: ['Git', 'History'] },
  { q: 'What does `git blame file.txt` show?', opts: ['Deletes the file from the working tree', 'Shows the commit and author behind each line', 'Restores the file to its previous version', 'Lists every commit that touched the file'], a: 1, e: '`git blame` prints the file with each line prefixed by the commit, author and date that last modified it, which is how you find the change that introduced a specific line. Listing the commits that touched the file as a whole is `git log -- file.txt`; blame works line by line and modifies nothing.', intro: 'Picture what fills the screen: a list of commits, or the contents of the file?', tags: ['Git', 'History'] },
  { q: 'What does this show?\n\n```bash\n$ git log -- file.txt\n```', opts: ['All commits', 'Only commits that changed file.txt', 'Only merges', 'File size history'], a: 1, e: 'A path after `--` limits the log to commits that changed that path, which is how you follow one file\'s history in a large repository. The `--` tells Git the rest are paths, so it will not confuse `file.txt` with a branch name of the same spelling; without a path, `git log` lists every commit reachable from HEAD.', intro: 'The `--` separates revision arguments from something else.', tags: ['Git', 'History'] },

  // ── Level 6 — Branches ─────────────────────────────────────────────────
  { q: 'With no arguments, what does `git branch` do?', opts: ['Creates a branch', 'Lists local branches', 'Deletes a branch', 'Switches branch'], a: 1, e: 'With no arguments `git branch` only reports: it lists local branches and marks the checked-out one with `*`. Creating, deleting and renaming all need an argument (`git branch <name>`, `-d`, `-m`) and switching is `git switch`; add `-r` or `-a` to see remote-tracking branches too.', intro: 'Compare it with `git branch feature`: the argument is what makes the command act.', tags: ['Git', 'Branches'] },
  { q: 'What does this do?\n\n```bash\n$ git branch feature\n```', opts: ['Switches the working tree to `feature`', 'Creates `feature` without switching to it', 'Deletes the branch named `feature`', 'Merges `feature` into the current branch'], a: 1, e: '`git branch feature` writes a new ref pointing at the current commit and leaves HEAD where it was, so your next commit still lands on the branch you were already on. Creating and switching in one step is `git switch -c feature`.', intro: 'After it runs, ask which commit HEAD points at.', tags: ['Git', 'Branches'] },
  { q: 'What does this do?\n\n```bash\n$ git switch feature\n```', opts: ['Creates it', 'Switches to the feature branch', 'Deletes it', 'Renames it'], a: 1, e: '`git switch feature` moves HEAD to the `feature` branch and updates the working tree to match it. The branch has to exist already, either locally or as a single remote-tracking branch Git can make a local copy of; with neither, it fails with `fatal: invalid reference`. Switch is the modern half of the old `git checkout`, whose other half — restoring files — is now `git restore`, and creating a brand-new branch as you switch needs `-c`.', intro: 'Compare it with `git switch -c feature` and name the one difference.', tags: ['Git', 'Branches'] },
  { q: 'What does this do?\n\n```bash\n$ git switch -c feature\n```', opts: ['Only creates it', 'Creates feature and switches to it', 'Only switches', 'Deletes it'], a: 1, e: '`-c` creates the named branch at the current commit and switches to it in one step — the documented equivalent of `git branch feature` followed by `git switch feature`, and of the older `git checkout -b`. Plain `git switch feature` requires the branch to exist already, and `git branch feature` alone would leave you where you were.', intro: 'Compare it with running `git branch feature` and then `git switch feature` back to back.', tags: ['Git', 'Branches'] },
  { q: 'A branch in Git is:', opts: ['A copy of all the files', 'A movable pointer to a commit', 'A remote server', 'A tag'], a: 1, e: 'A branch is a ref: a file holding one commit id (41 bytes on disk), which Git advances to each new commit you make while it is checked out. Nothing is copied when you create one, which is why branching is instant; a tag is the same shape but is meant to stay put.', intro: 'Ask what `.git/refs/heads/<name>` actually contains.', tags: ['Git', 'Branches'] },
  { q: 'What does this do?\n\n```bash\n$ git branch -d feature\n```', opts: ['Force-deletes always', 'Deletes feature if it’s already merged', 'Renames it', 'Archives it'], a: 1, e: '`-d` refuses to delete a branch whose commits are not reachable from somewhere else, printing \'the branch is not fully merged\' and changing nothing, so it protects work you would otherwise have to recover from the reflog. `-D` skips that check and deletes regardless; neither command renames or archives anything.', intro: 'Ask what Git would do if the branch still held commits that exist nowhere else.', tags: ['Git', 'Branches'] },
  { q: 'On hosting platforms such as GitHub and GitLab, what is a new repository\'s default branch called today?', opts: ['root', 'main', 'trunk', 'head'], a: 1, e: 'Hosting platforms create new repositories with `main` (GitHub changed this default in 2020), so that is the name a clone checks out. Git itself is a separate matter: through 2.43 `git init` still falls back to `master` unless `init.defaultBranch` is set, and the manual says that fallback becomes `main` in Git 3.0. `trunk` is Subversion\'s convention, `HEAD` is a pointer rather than a branch name, and `root` is neither.', intro: 'Recall what `origin/HEAD` pointed at in the last repository you cloned from a hosting platform.', tags: ['Git', 'Branches'] },
  { q: 'What does this do?\n\n```bash\n$ git branch -m old new\n```', opts: ['Moves a commit', 'Renames branch `old` to `new`', 'Merges them', 'Deletes old'], a: 1, e: '`git branch -m old new` renames the local branch `old` to `new`, keeping its commits and, where it can, its upstream configuration; with a single argument it renames the branch you are on. No commits move, nothing is merged and nothing is deleted — but a branch that already exists on a remote keeps its old name there until you push the new one and delete the old.', intro: 'Two names are given and neither is a commit; decide what the pair identifies.', tags: ['Git', 'Branches'] },

  // ── Level 7 — Merging ──────────────────────────────────────────────────
  { q: 'You’re on main. What does `git merge feature` do?', opts: ['Rebases feature', 'Merges feature into main (the current branch)', 'Deletes feature', 'Pushes feature'], a: 1, e: '`git merge feature` brings the named branch\'s commits into the branch you have checked out, so on `main` the merge advances `main` and leaves `feature` pointing exactly where it was. Rebasing, deleting and pushing are separate commands, and a merge never removes the branch it merged from.', intro: 'The command names one branch but two are involved; decide which one changes.', tags: ['Git', 'Merging'] },
  { q: 'When does a fast-forward merge happen?', opts: ['When the two branches changed the same lines', 'When the current branch has no commits of its own since the branch point', 'When you pass `--no-ff` to the merge', 'When the branches share no common ancestor'], a: 1, e: 'If the branch you are on is an ancestor of the branch you are merging, Git has nothing to combine: it moves the pointer forward and records no merge commit (`Updating <old>..<new>` / `Fast-forward`, one parent). Once the current branch has its own commits the histories have diverged and Git must create a merge commit, and `--no-ff` asks for one even when a fast-forward was available.', intro: 'Git prints `Fast-forward` and creates no new commit. Ask what the two histories must look like for that.', tags: ['Git', 'Merging'] },
  { q: 'You merge one branch into another and Git records a merge commit. How many parents does that commit have?', opts: ['Zero', 'One', 'Two', 'Three'], a: 2, e: 'Merging one branch into another produces a commit with two parents — the previous tip of the branch you were on and the tip of the branch you merged — which is what keeps both histories reachable afterwards. One parent means an ordinary commit or a fast-forward, where no merge commit is created at all; more than two parents only comes from an octopus merge, where you name several branches in one `git merge` command.', intro: 'Every branch the merge joined has to stay reachable from the new commit; count them.', tags: ['Git', 'Merging'] },
  { q: 'What does `git merge --no-ff feature` guarantee?', opts: ['It merges without recording a merge commit', 'It records a merge commit even when a fast-forward was possible', 'It rebases the branch onto the current one', 'It combines the branch\'s commits into a single commit'], a: 1, e: '`--no-ff` tells Git not to move the pointer even when it could, so the merge always creates a commit with two parents and the branch\'s shape stays visible in `git log --graph`. `--squash` goes the other way: it stages the branch\'s changes for one ordinary commit you make yourself and records no merge at all, while rebase rewrites the commits onto the target instead of joining histories.', intro: 'Read the flag as \'no fast-forward\' and decide what Git has to do instead.', tags: ['Git', 'Merging'] },
  { q: 'To merge feature into main, which branch should you be on?', opts: ['feature', 'main — the branch that will receive the changes', 'a detached HEAD', 'the remote'], a: 1, e: 'You check out the receiving branch first, then merge the other branch into it.', tags: ['Git', 'Merging'] },
  { q: 'What does `git merge --abort` do?', opts: ['Finishes the merge by committing the result', 'Cancels the merge and restores the pre-merge state', 'Deletes the branch that was being merged', 'Keeps the conflict markers and continues'], a: 1, e: 'During a conflicted merge Git still knows the commit you were on, so `--abort` resets the index and working tree back to it and clears MERGE_HEAD: no commit is made and your files lose the conflict markers. Committing the result is what you do after resolving instead, and no branch is deleted either way.', intro: 'Think about what Git recorded before it wrote conflict markers into your files.', tags: ['Git', 'Merging'] },
  { q: 'What does `git merge --squash feature` do?', opts: ['Records the branch\'s commits unchanged on the current branch', 'Stages the branch\'s combined changes for you to commit once', 'Rebases the branch onto the current branch', 'Creates a merge commit with two parents'], a: 1, e: '`--squash` applies the branch\'s combined changes to your working tree and index and then stops, printing \'Squash commit -- not updating HEAD\', so you write one ordinary commit with a single parent. The branch\'s individual commits are not copied and no merge is recorded, which is why `git branch --merged` still does not list the branch afterwards.', intro: 'Run it and then check `git status`: has Git committed anything yet?', tags: ['Git', 'Merging'] },
  { q: 'After a successful merge, the feature branch:', opts: ['Is deleted automatically', 'Still exists until you delete it', 'Becomes the remote', 'Is archived'], a: 1, e: 'A merge only updates the branch you are on; the source branch\'s ref is untouched and still appears in `git branch`, so you delete it yourself with `git branch -d feature` when it is no longer useful. Hosting platforms can delete the remote branch automatically after a pull request, but that is a platform setting, not something `git merge` does.', intro: 'Picture the `git branch` list immediately after the merge finishes.', tags: ['Git', 'Merging'] },

  // ── Level 8 — Remotes ──────────────────────────────────────────────────
  { q: 'What does `git remote -v` show?', opts: ['Branches', 'The configured remotes and their URLs', 'The Git version', 'It adds a remote'], a: 1, e: 'Plain `git remote` prints only the names; `-v` adds each remote\'s fetch URL and push URL, which is how you confirm where a clone really pulls from and pushes to when the two can differ. It lists no branches — that is `git branch -r` — and it never adds or modifies a remote.', intro: 'Compare it with plain `git remote`, which prints one word per remote.', tags: ['Git', 'Remotes'] },
  { q: 'What does this do?\n\n```bash\n$ git remote add origin <url>\n```', opts: ['Removes the remote named `origin`', 'Registers `origin` as a name for that URL', 'Renames an existing remote to `origin`', 'Clones the repository at that URL'], a: 1, e: '`git remote add <name> <url>` writes a remote section into `.git/config` with the URL and a fetch refspec, so later commands can say `origin` instead of the full URL. It moves no data by itself — you still need `git fetch` or `git push` — and it neither creates a local repository the way `git clone` does nor touches an existing remote.', intro: 'Notice the verb is `add`, and ask what has to exist before the command and what exists after.', tags: ['Git', 'Remotes'] },
  { q: 'A remote is:', opts: ['A branch stored in your local repository', 'A named URL for another copy of the repository', 'A commit that exists only on a server', 'A tag that marks a released version'], a: 1, e: 'A remote is a name Git stores for the URL of another copy of the repository, so you can fetch from it and push to it by name — `origin` after a clone. It is not a branch: the refs you see under it, such as `origin/main`, are remote-tracking branches created from what that remote reported, and it is neither a commit nor a tag.', intro: 'Ask what `origin` actually stores in `.git/config`.', tags: ['Git', 'Remotes'] },
  { q: 'What is `origin/main`?', opts: ['Your local `main` branch under another name', 'A remote-tracking ref: `main` as of your last fetch', 'A tag marking the released version of `main`', 'The staging area for changes going to the remote'], a: 1, e: '`origin/main` is a remote-tracking ref recording where `main` was on `origin` the last time Git contacted it — at clone, fetch, pull or push. It does not move while you commit locally, which is exactly how `git status` can tell you that you are \'ahead 1\'; it catches up only when Git next talks to the remote.', intro: 'You commit locally and `git status` says \'ahead 1\'. Ask what it compared your branch with.', tags: ['Git', 'Remotes'] },
  { q: 'What does `git fetch origin` do?', opts: ['Merges origin\'s commits into your current branch', 'Downloads origin\'s new commits and updates remote-tracking refs', 'Uploads your local commits to origin', 'Removes the origin remote from your config'], a: 1, e: 'git fetch downloads new objects and advances the remote-tracking refs (origin/main and friends). Your checked-out branch, index and working tree are untouched, which is why git status then reports the branch as behind. Merging those commits in is a separate step, and it is exactly what git pull adds; nothing is uploaded and no configuration is removed.', intro: 'Ask which refs move: the ones named origin/*, or the branch you have checked out?', tags: ['Git', 'Remotes'] },
  { q: 'What does `git remote remove origin` do?', opts: ['Deletes the repository', 'Removes the remote named origin', 'Renames origin', 'Clones origin'], a: 1, e: 'git remote remove origin deletes the remote\'s entry from .git/config together with its remote-tracking refs (origin/*). Your commits, branches and working tree are untouched, and so is the repository on the server — the \'deletes the repository\' option confuses the local pointer with the thing it points at. Renaming a remote is git remote rename, not remove.', intro: 'Decide what a remote actually is inside .git/config before you decide what removing it can destroy.', tags: ['Git', 'Remotes'] },
  { q: 'git clone gives the repository you cloned from a default remote name. Which statement about that name is correct?', opts: ['`main` — the remote takes the default branch\'s name', '`origin` — a default label you are free to rename', '`remote` — a reserved word every repository must use', '`server` — a name fixed by the hosting platform'], a: 1, e: 'git clone writes the source remote into .git/config under the name origin, and git remote rename origin upstream changes it, so origin is a convention rather than a keyword. main is a branch name, which is the usual mix-up. Git reserves neither remote nor server, and the hosting platform never dictates the local name you use.', intro: 'Recall which of these words git clone actually writes into .git/config, and which are just branch or server vocabulary.', tags: ['Git', 'Remotes'] },
  { q: 'What does this do?\n\n```bash\n$ git remote rename origin upstream\n```', opts: ['Deletes the origin remote and its tracking refs', 'Renames the remote origin to upstream, locally', 'Adds a second remote named upstream', 'Fetches from origin into a remote named upstream'], a: 1, e: 'The remote\'s entry in .git/config is renamed and its remote-tracking refs move with it, so origin/main becomes upstream/main. Nothing is added or deleted and no objects are transferred; a second remote would need git remote add, and fetching is a separate command. The server never learns which local name you use for it.', intro: 'Count your remotes before and after this runs. Ask whether the number goes up, down, or stays the same.', tags: ['Git', 'Remotes'] },

  // ── Level 9 — Push & Pull ──────────────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git push origin main\n```', opts: ['Downloads origin\'s main into your local main', 'Uploads your local main commits to origin\'s main', 'Deletes the main branch on origin', 'Merges origin\'s main into your local main'], a: 1, e: 'git push <remote> <branch> sends the commits on your local main to origin and moves origin\'s main to match, provided the update is a fast-forward. Downloading is git fetch, integrating is local work done by merge or rebase, and deleting the remote branch needs git push origin --delete main.', intro: 'Two names follow the verb: one is a remote, one is a branch. Decide which way the objects travel.', tags: ['Git', 'Push/Pull'] },
  { q: 'What does `git pull` do?', opts: ['Downloads new commits and stops there', 'Downloads new commits and integrates them into the current branch', 'Uploads your commits to the tracked remote branch', 'Rebases your commits onto the upstream branch every time'], a: 1, e: 'git pull runs git fetch and then integrates the upstream branch into the branch you are on. If your branch has not diverged the integration is a fast-forward; if it has, Git 2.34 and later stop with \'Need to specify how to reconcile divergent branches\' until you choose merge (pull.rebase false), rebase (pull.rebase true) or pull.ff only. It never pushes, and it rebases only when you configure or ask for it.', intro: 'Your working tree usually changes after this command. Ask what must have happened to your branch for that to be true.', tags: ['Git', 'Push/Pull'] },
  { q: 'What does the -u flag do here?\n\n```bash\n$ git push -u origin main\n```', opts: ['Pushes main once, without recording anything', 'Pushes main and records origin/main as its upstream', 'Removes the upstream link from the local branch', 'Pulls origin/main before pushing main'], a: 1, e: '-u (--set-upstream) sets branch.main.remote=origin and branch.main.merge=refs/heads/main, so a later bare git push or git pull knows where to go and git status can report ahead/behind. Without it, a brand-new branch\'s plain push fails with \'The current branch has no upstream branch\'. The flag neither pulls first nor removes any link.', intro: 'Picture the next push from this branch with no arguments. Ask what would have to be true already for it to work.', tags: ['Git', 'Push/Pull'] },
  { q: 'Your branch has two local commits while its upstream gained three commits. What does `git pull --rebase` try to do?', opts: ['Fetch and create a merge commit joining both histories', 'Fetch, then replay the two local commits on the updated upstream', 'Replace the remote branch with the two local commits', 'Discard the two local commits and reset to upstream'], a: 1, e: 'git pull --rebase fetches, then rebases: your two local commits are re-applied one at a time on top of the three new upstream commits, so the history stays linear and your two commits get new hashes. A merge commit joining both lines is what git pull with pull.rebase=false produces. Nothing is pushed, and --rebase never discards your commits or resets the branch to upstream.', intro: 'Nothing is joined here — one side\'s commits are re-created. Decide which side gets rewritten, yours or the upstream\'s.', tags: ['Git', 'Push/Pull'] },
  { q: 'Why might a push be rejected (non-fast-forward)?', opts: ['Your local branch has uncommitted changes', 'The remote branch has commits your branch does not contain', 'Your branch is ahead of the remote by more than one commit', 'You lack write permission on the remote'], a: 1, e: 'A push fast-forwards only when the remote\'s tip is an ancestor of the commit you are pushing. If a teammate pushed first it is not, so Git rejects the update instead of dropping their work: \'Updates were rejected because the remote contains work that you do not have locally\'. Fetch and integrate, then push. Uncommitted changes play no part in a push, and a permissions problem is reported as a denied ref update, not as non-fast-forward.', intro: 'Fast-forward means the remote\'s current tip is an ancestor of what you are pushing. Ask what breaks that relationship.', tags: ['Git', 'Push/Pull'] },
  { q: 'What does `git push --force-with-lease` do?', opts: ['Overwrites the remote branch unconditionally', 'Overwrites it only if the remote still matches your remote-tracking ref', 'Pulls the remote branch before overwriting it', 'Overwrites the remote branch and tags the result'], a: 1, e: '--force-with-lease overwrites only while the remote ref still points where your origin/<branch> says it does, so a teammate\'s push turns the force-push into \'! [rejected] ... (stale info)\' instead of silently deleting their commits. Plain --force skips that check and always wins. One caveat: any git fetch refreshes the lease, so fetch, look at what arrived, and only then retry.', intro: 'Picture a teammate pushing between your last fetch and this command. Ask whether Git has any way to notice.', tags: ['Git', 'Push/Pull'] },
  { q: 'How do `git fetch` and `git pull` differ?', opts: ['They’re identical', 'fetch only downloads; pull downloads and integrates into your branch', 'pull is read-only', 'fetch merges'], a: 1, e: 'fetch updates remote-tracking branches; pull additionally merges (or rebases) those changes in.', tags: ['Git', 'Push/Pull'] },
  { q: 'What does this do for a brand-new local branch?\n\n```bash\n$ git push -u origin feature\n```', opts: ['Fails, because feature does not exist on origin yet', 'Creates feature on origin and sets it to track', 'Renames origin\'s main branch to feature', 'Creates feature only locally, leaving origin unchanged'], a: 1, e: 'The push creates refs/heads/feature on origin from your local branch, and -u records origin/feature as its upstream so later push and pull need no arguments. You never have to create the branch on the server first. Without -u the branch is still published, but the next plain git push fails with \'no upstream branch\' unless push.autoSetupRemote is enabled, which it is not by default.', intro: 'Ask what the remote does with a branch name it has never seen before.', tags: ['Git', 'Push/Pull'] },

  // ── Level 10 — Undoing Changes ─────────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git restore file.txt\n```', opts: ['Stages the current contents of file.txt', 'Discards unstaged changes in file.txt, restoring it from the index', 'Deletes file.txt from the working tree', 'Commits the current contents of file.txt'], a: 1, e: 'git restore <file> overwrites the working-tree copy with the version in the index, so unstaged edits are discarded with no reflog to recover them. If you had staged an earlier version, that staged content is what comes back, not HEAD\'s; git restore --source=HEAD file.txt asks for the committed version instead. It does not stage, commit or delete anything.', intro: '`git restore` and `git restore --staged` rewrite different copies of the file. Ask which copy the bare form touches.', tags: ['Git', 'Undoing'] },
  { q: 'What does `git revert <commit>` do?', opts: ['Deletes that commit from the branch\'s history', 'Creates a new commit that undoes that commit\'s changes', 'Moves the branch pointer back to before that commit', 'Amends that commit in place with the inverse change'], a: 1, e: 'revert computes the inverse of the named commit and records it as a new commit on top, so both the original and its undo remain in the history and nothing already pushed is rewritten. Moving the branch pointer back is what reset does, and amending replaces a commit — both rewrite history and need a force-push, which is why revert is the safe choice on a shared branch.', intro: 'Ask what `git log` shows afterwards: fewer commits than before, the same number, or one more.', tags: ['Git', 'Undoing'] },
  { q: 'What does this do?\n\n```bash\n$ git reset --soft HEAD~1\n```', opts: ['Moves HEAD back one commit and discards the changes', 'Moves HEAD back one commit but keeps the changes staged', 'Moves HEAD back one commit and leaves the changes unstaged', 'Deletes the last commit and removes its files from disk'], a: 1, e: '--soft moves only the branch pointer, so the index and working tree still hold the undone commit\'s content and git status shows it staged, ready to re-commit with a better message. --mixed, the default, would also reset the index and leave the changes unstaged; --hard would reset the working tree as well and lose them.', intro: 'Reset always moves the branch pointer; the modes differ in how much follows it. Ask which parts --soft leaves alone.', tags: ['Git', 'Undoing'] },
  { q: 'What does this do?\n\n```bash\n$ git reset --hard HEAD~1\n```', opts: ['Moves HEAD back one commit and keeps the changes staged', 'Removes the last commit and discards its changes from the working tree', 'Records a new commit that undoes the last one', 'Moves HEAD back one commit and leaves the changes unstaged'], a: 1, e: '--hard resets the branch pointer, the index and the working tree together, so the commit\'s changes are wiped from disk. The commit object itself survives for a while and git reflog can bring it back, but anything never committed is gone for good. --soft would leave the changes staged, --mixed unstaged, and git revert would add an inverse commit rather than remove one.', intro: 'Ask how far this mode reaches: the branch pointer only, the index too, or your files on disk as well?', tags: ['Git', 'Undoing'] },
  { q: 'What does this do?\n\n```bash\n$ git restore --staged file.txt\n```', opts: ['Deletes file.txt from the working tree', 'Unstages file.txt while keeping your edits', 'Discards your edits to file.txt as well', 'Commits the staged version of file.txt'], a: 1, e: 'restore --staged copies the file from HEAD back into the index, so it is no longer staged, and it deliberately leaves the working tree alone: your edits remain as an unstaged change. Dropping the edits too takes git restore --staged --worktree file.txt. Nothing is committed and nothing is deleted.', intro: '--staged names which copy gets rewritten. Ask what happens to the other copy, the one open in your editor.', tags: ['Git', 'Undoing'] },
  { q: 'Which is safe to undo a commit that others have already pulled?', opts: ['`git reset --hard` on the shared branch, then force-push', '`git revert` the commit, then push normally', '`git reset --soft`, re-commit, then force-push', '`git commit --amend`, then force-push'], a: 1, e: 'revert adds a new commit whose content is the inverse, so the history everyone already fetched stays intact and an ordinary push is enough. reset (hard or soft) and commit --amend all replace commits and then require a force-push; collaborators keep the old commits, and their next pull brings back duplicates and conflicts. That is the same reasoning as the golden rule of rebasing.', intro: 'Everyone else already has that commit in their clone. Ask which option leaves their copy of the history still valid.', tags: ['Git', 'Undoing'] },
  { q: 'What does this older command do?\n\n```bash\n$ git checkout -- file.txt\n```', opts: ['Stages the file', 'Discards working-tree changes to file.txt', 'Switches branch', 'Deletes the file'], a: 1, e: 'The `--` marks what follows as a path, so this form restores file.txt from the index and throws away unstaged edits instead of switching branches. That overloading of checkout is why Git 2.23 split it into git switch for branches and git restore for files; git restore file.txt is the modern spelling of this command. It neither stages nor deletes the file.', intro: 'The `--` is doing the work here. Ask what it tells Git the following name is: a branch, or a path.', tags: ['Git', 'Undoing'] },
  { q: 'What does this do?\n\n```bash\n$ git clean -fd\n```', opts: ['Unstages files without deleting them', 'Deletes untracked files and directories', 'Deletes every file matched by .gitignore', 'Resets tracked files to their committed contents'], a: 1, e: 'git clean deletes untracked files; -f is required because the deletion is irreversible, and -d extends it to untracked directories. Ignored files are deliberately left alone unless you add -x, so the .gitignore option is wrong. Tracked files are never touched: restoring those is git restore, and unstaging is git restore --staged.', intro: 'Clean only touches files Git is not tracking. Ask which of those the -d adds to the default set.', tags: ['Git', 'Undoing'] },

  // ── Level 11 — Stashing ────────────────────────────────────────────────
  { q: 'What does `git stash` do?', opts: ['Records your changes as a commit on the current branch', 'Shelves your uncommitted tracked changes and cleans the working tree', 'Deletes your uncommitted changes permanently', 'Uploads your uncommitted changes to the remote'], a: 1, e: 'git stash saves your modified tracked files and staged changes onto a stack of stash entries, then resets the working tree to HEAD so a checkout or pull can proceed. Untracked files stay where they are unless you add -u. Nothing is committed to the branch, nothing is destroyed (git stash pop brings it back) and nothing reaches a remote.', intro: 'Ask where the changes end up and what the working tree looks like the moment the command returns.', tags: ['Git', 'Stash'] },
  { q: 'What does `git stash pop` do?', opts: ['Saves a new stash', 'Reapplies the latest stash and removes it from the stash list', 'Lists stashes', 'Clears all stashes'], a: 1, e: 'pop applies the most recent stash and then drops it.', tags: ['Git', 'Stash'] },
  { q: 'What does `git stash list` show?', opts: ['The files changed inside the most recent stash', 'The saved stash entries, newest first as stash@{0}', 'The stash entries saved by everyone who cloned the repository', 'The commits that were stashed and later dropped'], a: 1, e: 'git stash list prints one line per stash entry, most recent first, labeled stash@{0}, stash@{1} and so on; those labels are what you pass to apply, pop, show and drop. The contents of a single entry come from git stash show. Entries live in your clone only, so no one else\'s stashes appear, and dropped entries leave the list immediately.', intro: 'Ask how many lines you would expect after stashing twice, and what each line has to tell you.', tags: ['Git', 'Stash'] },
  { q: 'How do `git stash apply` and `git stash pop` differ?', opts: ['apply and pop do exactly the same thing', 'apply keeps the stash entry; pop applies it and then drops it', 'apply deletes the stash entry; pop keeps it', 'apply restores untracked files; pop restores tracked ones'], a: 1, e: 'Both commands re-apply the stashed changes; the difference is bookkeeping. pop drops the entry once it applies cleanly (it prints \'Dropped refs/stash@{0}\'), while apply leaves it in the list so the same work can be applied to a second branch. If the application conflicts, pop keeps the entry rather than losing it. Neither command is about tracked versus untracked files, which is what -u controls.', intro: 'Both put the changes back. Ask what the stash list looks like afterwards in each case.', tags: ['Git', 'Stash'] },
  { q: 'What does the -u flag add here?\n\n```bash\n$ git stash -u\n```', opts: ['Ignores untracked files', 'Also stashes untracked files', 'Stashes only untracked files', 'Unstages everything'], a: 1, e: '-u (--include-untracked) stashes untracked files alongside the modified tracked ones, so the working tree really is clean afterwards; without it a brand-new file stays put and can still block a checkout or poison a build. The flag is additive, not exclusive: tracked changes are stashed either way. Ignored files need -a (--all).', intro: 'Plain `git stash` leaves one category of file exactly where it is. Ask which category, and what `-u` does about it.', tags: ['Git', 'Stash'] },
  { q: 'You are half-way through a change when an urgent fix is needed on another branch. Why reach for `git stash`?', opts: ['It commits the half-finished work so the branch is clean', 'It sets the half-finished work aside so you can switch and restore it later', 'It deletes the half-finished work so the checkout can proceed', 'It pushes the half-finished work to the remote for safekeeping'], a: 1, e: 'Stash moves the unfinished changes off the working tree onto a local stack, so a checkout that would otherwise refuse to overwrite them can proceed, and git stash pop restores them when you come back. It does not commit them to the branch, discard them, or send them anywhere. A work-in-progress commit or a second worktree solve the same problem differently; stash is the option that leaves the branch history untouched.', intro: 'Two things have to hold here: the other branch has to check out, and your edits have to still be there when you come back.', tags: ['Git', 'Stash'] },
  { q: 'What does `git stash drop` do?', opts: ['Applies a stash entry and keeps it in the list', 'Deletes one stash entry without applying it', 'Deletes every stash entry at once', 'Applies a stash entry and then deletes it'], a: 1, e: 'drop removes a single entry (stash@{0} unless you name another) and discards its contents; nothing is applied to the working tree. Applying and then removing is pop, and removing every entry at once is git stash clear. drop prints the dropped commit\'s hash, and that object survives in the repository until garbage collection, so an accidental drop can sometimes still be recovered with git stash apply <hash>.', intro: 'Two things can happen to a stash entry: it can be applied, and it can be removed. Ask how many of them drop does.', tags: ['Git', 'Stash'] },
  { q: 'Where do stashes live?', opts: ['On the remote, once you push the branch', 'In your local repository only, under refs/stash', 'In a hidden branch that clone copies along', 'In the repository\'s .git/config file'], a: 1, e: 'A stash entry is a commit recorded under the local ref refs/stash, with a reflog holding the older entries. push and fetch move refs/heads/* and refs/tags/*, so stashes never leave the machine and a fresh clone has none of them. Treat the stash as scratch space, not backup: anything you cannot afford to lose belongs on a branch you push.', intro: 'Ask which refs a push actually sends, and whether a stash entry is one of them.', tags: ['Git', 'Stash'] },

  // ── Level 12 — Rebasing ────────────────────────────────────────────────
  { q: 'On feature, what does `git rebase main` do?', opts: ['Merges main into feature, adding a merge commit', 'Replays feature\'s commits on top of the latest main', 'Replays main\'s commits on top of feature', 'Moves the main branch pointer to feature\'s tip'], a: 1, e: 'From feature, git rebase main takes the commits that are on feature but not on main and re-applies them one at a time on main\'s current tip, so feature ends up ahead of main in a straight line and its commits get new hashes. No merge commit is written and main itself does not move — reading the argument as \'the branch that gets replayed\' is the usual mistake.', intro: 'The branch you are standing on is the one that moves. Decide whose commits get new parents.', tags: ['Git', 'Rebase'] },
  { q: 'How does rebase differ from merge?', opts: ['Rebase records a merge commit with two parents; merge does not', 'Rebase re-creates commits for a linear history; merge records a merge commit', 'Rebase and merge produce identical history; only the command differs', 'Rebase preserves the original commit hashes; merge changes them'], a: 1, e: 'Rebase re-applies your commits onto the new base, creating new commit objects with new hashes and leaving a straight line. Merge writes one new commit with two parents and leaves every existing commit exactly as it was. The trade-off is a readable linear log against an accurate record of when the branches diverged; the files you end up with are the same either way.', intro: 'Both bring one branch up to date with another. Ask which of them leaves the original commit objects untouched.', tags: ['Git', 'Rebase'] },
  { q: 'What does this let you do?\n\n```bash\n$ git rebase -i HEAD~3\n```', opts: ['Deletes the last 3 commits and their changes', 'Opens a todo list to reorder, squash, reword or drop the last 3 commits', 'Reverts the last 3 commits with 3 new inverse commits', 'Pushes the last 3 commits to the remote one at a time'], a: 1, e: 'rebase -i writes a todo list of the three commits after HEAD~3 and opens it in your editor. Each line starts with pick; changing it to reword, edit, squash, fixup or drop, or reordering the lines, tells Git how to replay that commit when you save. The range is re-created with new hashes, so this is for commits you have not shared. Reverting, by contrast, adds new commits and leaves the old ones in place.', intro: 'Ask what `HEAD~3` selects here, and whether selecting commits is the same as removing them.', tags: ['Git', 'Rebase'] },
  { q: 'Why is rebasing commits that others have already pulled discouraged?', opts: ['Rebase cannot be run on commits that exist on a remote', 'It replaces those commits with new ones, so collaborators end up holding both', 'Rebase deletes the collaborators\' local branches on their next fetch', 'Remotes reject any push that contains rebased commits'], a: 1, e: 'Rebasing abandons the existing commits and creates similar but different ones, so anyone who based work on the originals now has both versions and has to re-merge; the Git book states it as \'do not rebase commits that exist outside your repository and that people may have based work on\'. Git itself does not prevent this — the remote only rejects the non-fast-forward push until you force it — which is why this is a discipline teams agree on rather than a rule the tool enforces. Rebasing your own unpushed commits is safe and encouraged.', intro: 'Rebasing gives the commits new hashes. Ask what that means for a teammate whose clone already stores the old ones.', tags: ['Git', 'Rebase'] },
  { q: 'After resolving a conflict mid-rebase, which command continues it?', opts: ['`git commit`', '`git rebase --continue`', '`git merge`', '`git push`'], a: 1, e: 'You stage the resolved files with git add and run git rebase --continue; Git finishes that commit and moves on to the next entry in the todo list. Running git commit instead does record the resolution, but the rebase stays in progress with the remaining commits unapplied and HEAD still detached, so you have to run --continue anyway. git merge and git push have no part in the loop, and Git prints the three real choices — --continue, --skip, --abort — with the conflict.', intro: 'The rebase is paused part-way through a list of commits. Ask which command knows there are more still to replay.', tags: ['Git', 'Rebase'] },
  { q: 'What does `git rebase --abort` do?', opts: ['Finishes the rebase, keeping the conflicted files as they are', 'Cancels it and restores the branch to its pre-rebase state', 'Skips the conflicting commit and continues with the rest', 'Keeps the commits already replayed and stops there'], a: 1, e: '--abort discards the partially replayed commits and moves the branch back to the commit it pointed at before the rebase began, restoring the working tree with it, so the conflicted files return to their original contents. Stopping but keeping the replayed commits is not on offer: --skip drops just the conflicting commit and carries on, and --continue finishes the rebase after you stage a resolution.', intro: 'Ask what happens to the commits that were already replayed when you decide to stop half-way.', tags: ['Git', 'Rebase'] },
  { q: 'In interactive rebase, what does `squash` (s) do to a commit?', opts: ['Drops it', 'Combines it into the previous commit', 'Reorders it', 'Edits only its message'], a: 1, e: 'squash folds the commit\'s changes into the commit on the line above it and opens an editor holding both messages so you can write one combined message. fixup does the same but throws the squashed commit\'s message away; drop removes the commit and its changes entirely; reword changes only the message. Reordering happens only if you move the lines yourself.', intro: 'Ask how many commits are left after the step, and what becomes of the two commit messages.', tags: ['Git', 'Rebase'] },
  { q: 'After rebasing a branch you had already pushed, you usually must:', opts: ['Push normally; the remote accepts the rewritten commits', 'Force-push, ideally with --force-with-lease, because the history was rewritten', 'Pull first and then push, which reconciles the rewritten commits', 'Delete the remote branch, since Git recreates it on the next push'], a: 1, e: 'Rebase re-creates the commits, so the remote\'s tip is no longer an ancestor of your branch and an ordinary push is rejected as non-fast-forward. --force-with-lease replaces the remote branch while still refusing if someone else pushed in the meantime. Pulling instead brings the old copies back: Git first asks how to reconcile the diverged branches, and merging leaves every commit duplicated.', intro: 'Rebase gave your commits new hashes. Ask how the remote sees a branch whose old tip is no longer an ancestor of yours.', tags: ['Git', 'Rebase'] },

  // ── Level 13 — Tags & .gitignore ───────────────────────────────────────
  { q: 'What does this do?\n\n```bash\n$ git tag v1.0\n```', opts: ['Creates a branch named v1.0 at the current commit', 'Creates a lightweight tag at the current commit', 'Creates an annotated tag with an empty message', 'Pushes the current commit to origin as release v1.0'], a: 1, e: 'With just a name, git tag writes a ref under refs/tags pointing straight at the current commit: a lightweight tag with no message, tagger or date of its own, which is why git cat-file -t v1.0 reports \'commit\'. Adding -a or -m instead creates an annotated tag, a separate object. Unlike a branch a tag does not move as you commit, and creating one sends nothing to any remote.', intro: 'There is no -a and no -m here. Ask how much Git can store when you give it only a name.', tags: ['Git', 'Tags'] },
  { q: 'What does this create?\n\n```bash\n$ git tag -a v1.0 -m "Release 1.0"\n```', opts: ['A lightweight tag', 'An annotated tag', 'A branch', 'A commit'], a: 1, e: '-a creates a tag object in the object database holding the tag name, the commit it points at, the tagger, the date and the message, so git cat-file -t v1.0 reports \'tag\' rather than \'commit\'. A lightweight tag is only a ref, with none of that. The extra object is the practical reason releases use annotated tags: git describe prefers them and push --follow-tags carries them, and they can be signed with -s.', intro: 'Compare what has to be stored for a message and an author with what a plain ref can hold.', tags: ['Git', 'Tags'] },
  { q: 'When are tags sent to a remote?', opts: ['Automatically, with every push of the branch they point into', 'Only when you push them explicitly, for example git push --tags', 'Automatically, the first time someone clones the repository', 'Never; tags exist only in the clone that created them'], a: 1, e: 'A plain git push sends only the branch being pushed, so a new tag stays local until you name it (git push origin v1.0) or send them all with --tags; --follow-tags, or push.followTags, opts in to carrying annotated tags along with the branch. A release tag that never reached the server is a common cause of a pipeline that will not build. Cloning and fetching are the other direction: they do bring tags down.', intro: 'A normal push sends the branch you name. Ask whether anything under refs/tags is included in that.', tags: ['Git', 'Tags'] },
  { q: 'What is a `.gitignore` file for?', opts: ['Listing files to delete', 'Listing patterns of files Git should not track', 'Storing commit messages', 'Configuring remotes'], a: 1, e: 'A .gitignore holds path patterns that Git keeps out of the untracked-files list in git status and refuses to add without -f, which is how build output, dependency directories and local secrets stay out of history. It governs only files Git is not already tracking, it deletes nothing from disk, and commit messages and remotes are configured elsewhere.', intro: 'Ask what Git does differently with a matching file: does anything vanish from disk, or only from a list?', tags: ['Git', 'gitignore'] },
  { q: 'You add an already-tracked file to `.gitignore`. What happens?', opts: ['Git removes it from the index on your next commit', 'It stays tracked until you untrack it, for example git rm --cached', 'It stays tracked, but its future changes stop appearing in git status', 'Git deletes the file from your working tree'], a: 1, e: 'An ignore pattern is consulted for untracked paths only, so a file already in the index keeps being tracked and its edits keep showing in git status and in every commit. git rm --cached <file> takes it out of the index while leaving it on disk, and only then does the rule apply. Nothing is removed from the working tree automatically, and a secret that is already committed stays in the history until that history is rewritten.', intro: 'The file is already in the index. Ask what adding a line to `.gitignore` can do to something that is already there.', tags: ['Git', 'gitignore'] },
  { q: 'What does this do?\n\n```bash\n$ git rm --cached secrets.env\n```', opts: ['Deletes secrets.env from disk and from the index', 'Stops tracking it but keeps it in your working directory', 'Adds secrets.env to .gitignore for you', 'Removes secrets.env from every past commit'], a: 1, e: 'git rm --cached deletes the path from the index and stages that deletion; the file itself stays on disk. That is why the sequence is: add the pattern to .gitignore, run git rm --cached, commit. It does not edit .gitignore for you, and it does not touch history — a credential that was already committed remains in every earlier commit until the history is rewritten and the credential rotated.', intro: 'The plain form of this command removes the file from both places. Ask which one --cached spares.', tags: ['Git', 'gitignore'] },
  { q: 'A release pipeline needs a stable name such as v2.3.0 for one exact commit. Which Git reference fits best?', opts: ['A branch named v2.3.0, updated whenever the release changes', 'A tag pointing to the release commit', 'The commit\'s abbreviated hash, pasted into the pipeline config', 'A remote-tracking ref such as origin/main'], a: 1, e: 'A tag is a named reference that is not expected to move, so v2.3.0 keeps meaning one commit and the pipeline can fetch, check out and verify it. A branch is expected to advance as commits land, so it cannot pin a release; origin/main moves with every merge. A raw hash is stable but unreadable and easy to mistype, which is exactly what a tag exists to fix.', intro: 'Ask which of these references is still expected to mean the same commit a year from now.', tags: ['Git', 'Tags'] },
  { q: 'You have just tagged the current commit as v1.0. What does this do?\n\n```bash\n$ git push origin v1.0\n```', opts: ['Pushes the branch v1.0 to origin', 'Pushes the v1.0 tag to origin', 'Pushes every tag in the repository to origin', 'Creates a release page on the hosting platform'], a: 1, e: 'Naming a single ref sends only that ref: the v1.0 tag is created on origin and nothing else moves. All tags at once would be --tags, and pushing a branch would need a branch of that name to exist. Pushing the tag is not the same as publishing a release — GitHub and GitLab build a release page from a tag afterwards, through their own UI or API — so the tag is the prerequisite, not the release.', intro: 'One ref is named here. Ask what Git sends when you name exactly one.', tags: ['Git', 'Tags'] },

  // ── Level 14 — Collaboration & PRs ─────────────────────────────────────
  { q: 'What is a pull request (PR)?', opts: ['A Git command that merges one branch into another', 'A hosting-platform proposal to merge a branch, with review and discussion', 'A request asking a maintainer to grant you push access', 'A copy of a repository made under your own account'], a: 1, e: 'A pull request is a feature of the hosting platform, not of Git: it points at a branch and asks the maintainers to review and merge it, collecting comments, approvals and status checks along the way. GitLab calls the same object a merge request. The merge it finally performs is an ordinary Git merge; copying a repository to your own account is a fork, and push access is granted in repository settings.', intro: 'Ask what the request is asking someone to do, and which system is keeping track of that request.', tags: ['Git', 'Collaboration'] },
  { q: 'Is `git fork` a core Git command?', opts: ['Yes; `git fork` copies a repository on the server', 'No; forking is a hosting feature that copies a repo to your account', 'Yes; `git fork` is an alias for `git clone`', 'No; forking is another name for creating a branch'], a: 1, e: 'Git has no fork subcommand — running it prints "git: \'fork\' is not a git command". Forking happens on GitHub, GitLab and similar: the server makes its own copy of the repository under your account, and you clone that copy. Cloning copies a repository onto your machine, and a branch is a ref inside a single repository, so neither is what forking means.', intro: 'Ask which machine does the copying: yours, or the server that holds the original.', tags: ['Git', 'Collaboration'] },
  { q: 'You have finished a change on a feature branch. What is the usual next step before it can be reviewed?', opts: ['Push the branch to the remote, then open a pull request', 'Merge the branch into main locally and push main', 'Open a pull request from the branch before pushing it', 'Force-push the branch over main on the remote'], a: 0, e: 'A pull request points at a branch that exists on the remote, so the branch is pushed first and the platform then shows its diff against the base branch and collects reviews. A pull request cannot reference commits the server has never received. Merging into main locally skips the review entirely, and force-pushing over main destroys other people\'s work.', intro: 'A reviewer has to be able to see the commits. Ask what must already be true on the server for that.', tags: ['Git', 'Collaboration'] },
  { q: 'In a fork workflow, the `upstream` remote usually points to:', opts: ['Your fork on the hosting platform', 'The original repository you forked from', 'The default branch of your fork', 'The maintainer\'s local clone'], a: 1, e: 'In a fork workflow origin is your own fork, the one you push to, and upstream is a second remote pointing at the project you forked from, so git fetch upstream brings in its new commits. These are conventional names, not something Git enforces — git remote rename will call them anything you like — but nearly every contributing guide uses them this way. A remote always names a repository, never a branch.', intro: 'You already have a remote for your own fork. Ask what a second remote would be for.', tags: ['Git', 'Collaboration'] },
  { q: 'How do you keep a fork up to date with the original?', opts: ['Fetch from upstream, integrate into your branch, then push to your fork', 'Push your fork\'s branch to upstream so the two match', 'Delete the fork and create a new one from the original', 'Clone the original repository again over your fork\'s directory'], a: 0, e: 'You fetch upstream, merge or rebase its commits into your local branch, and push the result to origin — your fork is the only remote you can write to. Pushing to upstream is what a pull request exists to replace, since contributors do not have write access there. Re-forking or re-cloning would throw away your own branches to solve a problem a fetch already solves.', intro: 'You can read from the original but not write to it. Ask which way the commits have to travel.', tags: ['Git', 'Collaboration'] },
  { q: 'What does requiring pull request review give a team?', opts: ['A recorded second opinion on the change before the branch merges', 'A guarantee that the merged change contains no bugs', 'An automatic rollback if the change breaks production', 'A merge that skips the repository\'s status checks'], a: 0, e: 'Review produces a recorded second opinion: reviewers comment, approve or request changes, and that record stays attached to the pull request after it merges. It is a human check, not a proof — defects still get through, which is why automated status checks run alongside it. Review never rolls a change back and never bypasses required checks.', intro: 'A reviewer is a person reading a diff. Ask what such a person can and cannot promise about the merged change.', tags: ['Git', 'Collaboration'] },
  { q: 'What does marking a PR as "draft" signal?', opts: ['It merges automatically once the checks pass', 'It marks the work in progress and blocks merging until it is marked ready', 'It hides the pull request from everyone but you', 'It closes the pull request until you reopen it'], a: 1, e: 'A draft pull request is visible to everyone who can see the repository, but it is flagged as work in progress: the platform disables merging until you mark it ready for review, and reviewers know a final pass would be premature. That is the whole effect — nothing is hidden, closed, or merged for you.', intro: 'Ask whether \'draft\' changes who can see the pull request, or only what can be done with it.', tags: ['Git', 'Collaboration'] },
  { q: 'Your pull request was merged with a merge commit. What happens to the commits if you now delete the feature branch?', opts: ['They are deleted along with the branch', 'They stay in the base branch\'s history; the branch was only a pointer', 'They stay only until Git next runs garbage collection', 'They must be cherry-picked into main before the branch can go'], a: 1, e: 'Merging makes the commits reachable from the base branch, so deleting the feature branch removes a pointer and nothing else — git log on main still lists them, and reachable objects are never garbage-collected. That is why hosting platforms offer to delete the branch straight after the merge. Cherry-picking is for commits that were not merged.', intro: 'Ask what the merge already did with those commits, before you touched the branch at all.', tags: ['Git', 'Collaboration'] },

  // ── Level 15 — Advanced Git ────────────────────────────────────────────
  { q: 'What does `git cherry-pick <commit>` do?', opts: ['Merges the whole branch that commit came from', 'Applies that one commit\'s changes as a new commit on the current branch', 'Moves the commit out of its original branch onto this one', 'Rebases the current branch onto that commit'], a: 1, e: 'cherry-pick takes the change that commit introduced and re-applies it on your current branch as a new commit with a new hash; the original stays exactly where it was, so this copies rather than moves. Nothing else from the source branch comes along, which is what separates it from a merge. Because the result is a second commit with the same change, merging the two branches later can show that change twice.', intro: 'Ask what is left behind on the original branch once the command finishes.', tags: ['Git', 'Advanced'] },
  { q: 'What does `git reflog` show?', opts: ['The commits reachable from the current branch, newest first', 'A local log of every position HEAD has held, including commits no branch points at', 'The refs that currently exist on the remote', 'The tags that point into the current branch\'s history'], a: 1, e: 'The reflog is a local journal of every move of HEAD and of each branch ref: checkouts, commits, resets, rebases, merges. Because it keeps the old hashes, a commit no branch points at any more is still findable and restorable, which git log cannot do since it only walks the current history. Reflogs live in your clone and expire (90 days by default), so treat them as a safety net rather than an archive.', intro: '`git log` answers what is in this branch now. Ask what the extra `ref` in `reflog` is a log of.', tags: ['Git', 'Advanced'] },
  { q: 'What does `git bisect` help you do?', opts: ['Splits a large repository into two smaller ones', 'Binary-searches history to find the commit that introduced a bug', 'Searches the diffs to find the line that introduced a bug', 'Splits a large commit into two smaller commits'], a: 1, e: 'bisect takes a known-good and a known-bad commit, checks out the midpoint and halves the range each time you mark a result, so a thousand commits take about ten tests; git bisect run <script> marks them for you. It identifies the commit, not the line — that is what git blame and git log -S are for — and it changes no history, since git bisect reset puts you back where you started.', intro: 'You know one commit where it worked and one where it does not. Ask what you can do with that pair.', tags: ['Git', 'Advanced'] },
  { q: 'What is a "detached HEAD"?', opts: ['A repository whose HEAD file has been corrupted', 'HEAD pointing directly at a commit instead of at a branch', 'A branch that has no upstream on any remote', 'A commit that no branch or tag can reach'], a: 1, e: 'Checking out a commit, a tag or a remote-tracking ref rather than a branch leaves HEAD pointing straight at a commit, and git status says \'HEAD detached at <sha>\'. Commits made there belong to no branch, so the moment you check something else out they become unreachable and only the reflog can find them — create a branch with git switch -c before committing. The repository is not broken, and an unreachable commit is the consequence, not the definition.', intro: 'Ask what `git checkout <sha>` gives HEAD to hold on to.', tags: ['Git', 'Advanced'] },
  { q: 'What is a Git submodule?', opts: ['A subfolder of your repository, tracked like any other directory', 'A reference to another repository, pinned at one commit inside yours', 'A second checkout of your own repository at another path', 'A copy of another repository\'s files committed into yours'], a: 1, e: 'A submodule records a gitlink at that path — mode 160000 plus a single commit hash — with the repository URL kept in .gitmodules; the files live in the other repository, so a plain clone leaves the directory empty until you use --recurse-submodules. Pinning one commit is the point: updates are explicit. Committing the files in directly is vendoring, and a second checkout of your own repository is a worktree.', intro: 'Ask what your repository actually stores at that path: the other project\'s files, or something much smaller.', tags: ['Git', 'Advanced'] },
  { q: 'What are Git hooks?', opts: ['Configuration entries that run commands on the remote', 'Scripts Git runs automatically on events such as pre-commit', 'Shorthand names you define for long Git commands', 'Settings that stop certain files from being committed'], a: 1, e: 'Hooks are executable scripts in .git/hooks (or wherever core.hooksPath points) that Git runs at fixed points — pre-commit, commit-msg, pre-push, post-merge and others — and a non-zero exit from a pre- hook cancels the operation, which is how lint and commit-message rules get enforced. They live in the clone and are not pushed, so teams install them with a tool or core.hooksPath. Aliases are commands you type; hooks are the ones you do not.', intro: 'Ask what Git could run on your behalf at a fixed moment, without you typing anything.', tags: ['Git', 'Advanced'] },
  { q: 'You ran `git reset --hard` and lost a commit that had never been pushed. How can you recover it?', opts: ['It is gone for good once the branch pointer moved', 'Find its hash in git reflog, then reset or check out to it', 'Pull from the remote, which still has the commit', 'Restore it with git stash pop'], a: 1, e: 'reset --hard only moved the branch pointer; the commit object stays in the repository until garbage collection removes unreachable objects. git reflog lists HEAD\'s previous positions with their hashes, so git reset --hard <hash> or checking it out onto a new branch brings it back. The commit was never pushed, so the remote cannot help, and the stash holds only what you explicitly stashed.', intro: 'Ask what `git reset --hard` actually destroyed: the commit object, or only the branch\'s claim on it.', tags: ['Git', 'Advanced'] },
  { q: 'A one-commit fix has landed on main, and the 1.x release branch needs that fix and nothing else. Which is the right tool?', opts: ['Merge main into 1.x', 'Cherry-pick the fix commit onto 1.x', 'Rebase 1.x onto main', 'Reset 1.x to main and re-apply the release commits'], a: 1, e: 'Cherry-pick applies just that commit\'s change to 1.x as a new commit, which is exactly what a backport needs. Merging or rebasing would drag everything else on main onto the release branch, and resetting would throw the release branch away. The cost worth knowing: the fix now exists as two commits with different hashes, so a later merge between the branches can present the same change twice.', intro: 'Ask how much of main each of these would bring along with the fix.', tags: ['Git', 'Advanced'] },
];
